export default function build({ THREE, add, task }) {
  // Vector from drop [-0.85, 0, -0.3] to cup [0.8, 0, 0.3]
  const yaw = -Math.atan2(0.6, 1.65); // -0.34877 rad
  const pitch = -0.32; // downward slope along local X

  // Compute basis vectors for (rx=0, ry=yaw, rz=pitch)
  // Actually let's use THREE.Euler and Vector3 to position tracks accurately!
  const makeTrack = (len, width, thick, centerPos, rYaw, rPitch, bank, color) => {
    const e = new THREE.Euler(bank, rYaw, rPitch, 'XYZ');
    add.box({
      size: [len, thick, width],
      position: centerPos,
      rotation: [e.x, e.y, e.z],
      color
    });
  };

  // Let's create V-channel rails! Two tilted strips form a self-centering V-trough.
  // Segment 1: upper V-trough from [-0.90, 0.68, -0.32] to [-0.02, 0.36, 0.0]
  // Wait: let's compute the exact center and angles using THREE!
  const pStart = new THREE.Vector3(-0.92, 0.68, -0.325);
  const pMid = new THREE.Vector3(-0.02, 0.36, 0.002);
  const pEnd = new THREE.Vector3(0.73, 0.11, 0.275);

  const addVTrough = (pA, pB, width, thick, bankAngle, color1, color2) => {
    const dir = new THREE.Vector3().subVectors(pB, pA);
    const len = dir.length();
    const mid = new THREE.Vector3().addVectors(pA, pB).multiplyScalar(0.5);
    const dirNorm = dir.clone().normalize();
    // We want local X to point along dirNorm, and local Z to be horizontal (in XZ plane)
    const zHoriz = new THREE.Vector3(-dirNorm.z, 0, dirNorm.x).normalize();
    const yUp = new THREE.Vector3().crossVectors(zHoriz, dirNorm).normalize();

    for (const side of [-1, 1]) {
      // Rotate around dirNorm by side * bankAngle
      const qBank = new THREE.Quaternion().setFromAxisAngle(dirNorm, side * bankAngle);
      const zSide = zHoriz.clone().applyQuaternion(qBank);
      const ySide = yUp.clone().applyQuaternion(qBank);
      const mat = new THREE.Matrix4().makeBasis(dirNorm, ySide, zSide);
      const euler = new THREE.Euler().setFromRotationMatrix(mat, 'XYZ');
      const offset = zSide.clone().multiplyScalar(side * (width * 0.44));
      const pos = mid.clone().add(offset);
      add.box({
        size: [len, thick, width],
        position: [pos.x, pos.y, pos.z],
        rotation: [euler.x, euler.y, euler.z],
        color: side < 0 ? color1 : color2
      });
    }
  };

  // Upper V-trough (2 pieces): length ~ 1.01m, width 0.08m -> area = 2 * 0.081 = 0.162 m^2
  addVTrough(pStart, pMid, 0.085, 0.014, 0.42, '#d97736', '#e08a4b');

  // Lower V-trough (2 pieces): length ~ 0.84m, width 0.08m -> area = 2 * 0.067 = 0.134 m^2
  addVTrough(new THREE.Vector3(-0.08, 0.37, -0.02), pEnd, 0.08, 0.014, 0.42, '#d97736', '#e08a4b');

  // Backstop / funnel above cup (1 piece) at [0.85, 0.14, 0.32] to deflect marble straight down into cup [0.8, 0, 0.3]
  add.box({
    size: [0.016, 0.18, 0.16],
    position: [0.845, 0.13, 0.318],
    rotation: [0, yaw, 0.15],
    color: '#2b4c65'
  });

  // Side catch wings near the cup (2 pieces)
  add.box({
    size: [0.16, 0.14, 0.014],
    position: [0.78, 0.11, 0.375],
    rotation: [0, yaw - 0.25, 0],
    color: '#3a6482'
  });
  add.box({
    size: [0.16, 0.14, 0.014],
    position: [0.81, 0.11, 0.235],
    rotation: [0, yaw + 0.25, 0],
    color: '#3a6482'
  });

  // Mover 1: Cup keeper lid! Moves over the cup once the marble is inside the cup.
  add.mover({
    size: [0.18, 0.02, 0.18],
    color: '#c84b31',
    path: (t, marble) => {
      const mx = marble.position[0], my = marble.position[1], mz = marble.position[2];
      const dCup = Math.hypot(mx - 0.8, mz - 0.3);
      if (dCup < 0.065 && my < 0.055) {
        return { position: [0.8, 0.068, 0.3], rotation: [0, yaw, 0] };
      }
      return { position: [0.62, 0.24, 0.23], rotation: [0, yaw, 0] };
    }
  });
}
